<div class="page-actions"><div><p class="muted">Penjualan barang kepada customer.</p></div><?php if(($currentUser['role']??'')==='Admin'):?><a class="btn btn-primary" href="?page=sales&action=create">+ Tambah Sales Order</a><?php endif;?></div>
<div class="card"><div class="table-wrap"><table><thead><tr><th>Nomor SO</th><th>Tanggal</th><th>Customer</th><th>Gudang</th><th>Total</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($result['items'] as $o):?><tr><td><a class="link" href="?page=sales&action=view&id=<?=$o['id']?>"><?=e($o['so_number'])?></a></td><td><?=e($o['so_date'])?></td><td><?=e($o['customer_name'])?></td><td><?=e($o['warehouse_name'])?></td><td>Rp <?=number_format((float)$o['total_amount'],0,',','.')?></td><td><span class="badge status-<?=strtolower((string)($o['status']??''))?>"><?=e($o['status'])?></span></td><td><?php if(($currentUser['role']??'')==='Admin'&&$o['status']!=='Completed'):?><form class="inline-form" method="post" action="?page=sales&action=status&id=<?=$o['id']?>"><?=$csrfField?><select name="status"><option value="Draft" <?=$o['status']==='Draft'?'selected':''?>>Draft</option><option value="Confirmed" <?=$o['status']==='Confirmed'?'selected':''?>>Confirmed</option><option value="Completed">Completed</option><option value="Cancelled">Cancelled</option></select><button class="btn btn-sm">Update</button></form><?php else:?>-<?php endif;?></td></tr><?php endforeach;?><?php if(!$result['items']):?><tr><td colspan="7" class="empty">Belum ada Sales Order.</td></tr><?php endif;?></tbody></table></div><?=paginationLinks($result,['page'=>'sales'])?></div>
